using System.Collections.Generic;
using System.Text.Json.Serialization;

namespace Adyen.Models;

public record FraudResult6
{
    /// <summary>
    /// The total fraud score generated by the risk checks.
    /// </summary>
    [JsonPropertyName("accountScore")]
    public required int AccountScore { get; init; }

    /// <summary>
    /// The result of the individual risk checks.
    /// </summary>
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    [JsonPropertyName("results")]
    public IReadOnlyList<FraudCheckResultWrapper>? Results { get; init; }
}
